const root=document.getElementById('agenda-view');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const categories=['Matéria-prima','Embalagens','Insumos','EPIs','Manutenção','Cimento','Diesel','Transporte','Serviços','Outros'];
let records=[],selected='',search='',category='Todos',editing=null;
const digits=v=>String(v||'').replace(/\D/g,'');
function whatsapp(phone){const d=digits(phone);if(!d)return '';return 'https://wa.me/'+(d.startsWith('55')?d:'55'+d);}
function logo(r){return r.photo?'<img src="'+esc(r.photo)+'" alt="Foto de '+esc(r.name)+'">':'<span>'+esc((r.name||r.company||'?').slice(0,2).toUpperCase())+'</span>';}
function sticker(r,i){return '<article class="agenda-sticker '+(selected===r.id?'chosen':'')+'"><button class="agenda-sticker-main" data-select="'+esc(r.id)+'" aria-label="Ver contato '+esc(r.name)+'"><span class="agenda-sticker-top"><b>COLAFIX</b><span>★ '+String(i+1).padStart(3,'0')+' ★</span></span><span class="agenda-avatar">'+logo(r)+'</span><strong title="'+esc(r.name)+'">'+esc(r.name)+'</strong><small title="'+esc(r.company)+'">'+esc(r.company)+'</small><em>'+esc(r.category)+'</em></button><div class="agenda-sticker-foot">'+(whatsapp(r.phone)?'<a href="'+whatsapp(r.phone)+'" target="_blank" rel="noopener noreferrer" aria-label="Abrir WhatsApp de '+esc(r.name)+'">☏ WhatsApp</a>':'<span>Sem WhatsApp</span>')+'</div></article>';}
function details(r){if(!r)return '<div class="agenda-placeholder">Selecione uma figurinha para ver os dados completos do contato.</div>';return '<div class="agenda-profile"><div class="agenda-profile-head"><span class="agenda-avatar">'+logo(r)+'</span><div><h3>'+esc(r.name)+'</h3><p>'+esc(r.company)+'</p><span class="agenda-pill">'+esc(r.category)+'</span></div></div><dl><dt>Cargo / função</dt><dd>'+esc(r.role||'—')+'</dd><dt>Materiais fornecidos</dt><dd>'+esc(r.materials||'—')+'</dd><dt>Telefone / WhatsApp</dt><dd>'+esc(r.phone||'—')+'</dd><dt>E-mail</dt><dd>'+esc(r.email||'—')+'</dd><dt>Observações</dt><dd>'+esc(r.notes||'—')+'</dd></dl><div class="agenda-profile-actions">'+(whatsapp(r.phone)?'<a class="agenda-wa" href="'+whatsapp(r.phone)+'" target="_blank" rel="noopener noreferrer">☏ Abrir WhatsApp</a>':'')+(r.email?'<a href="https://outlook.office.com/mail/deeplink/compose?to='+encodeURIComponent(r.email)+'" target="_blank" rel="noopener noreferrer">✉ E-mail</a>':'')+'<button data-edit="'+esc(r.id)+'">✎ Editar</button><button data-remove="'+esc(r.id)+'" class="agenda-danger">Excluir</button></div></div>';}
function form(r){return '<form id="agenda-form" class="agenda-form"><div class="agenda-form-title"><h3>'+(r?'Editar figurinha':'Nova figurinha')+'</h3><button type="button" data-cancel>✕</button></div><div class="agenda-form-grid"><label>Empresa *<input name="company" required maxlength="160" value="'+esc(r?.company||'')+'"></label><label>Nome do contato *<input name="name" required maxlength="160" value="'+esc(r?.name||'')+'"></label><label>Categoria de material<select name="category">'+categories.map(c=>'<option '+(c===(r?.category||'Matéria-prima')?'selected':'')+'>'+esc(c)+'</option>').join('')+'</select></label><label>Cargo / função<input name="role" maxlength="100" value="'+esc(r?.role||'')+'"></label><label>WhatsApp / telefone<input name="phone" inputmode="tel" maxlength="30" placeholder="(51) 99999-9999" value="'+esc(r?.phone||'')+'"></label><label>E-mail<input name="email" type="email" maxlength="180" value="'+esc(r?.email||'')+'"></label><label class="agenda-wide">Materiais fornecidos<input name="materials" maxlength="500" placeholder="Ex.: sacarias, caixas, etiquetas" value="'+esc(r?.materials||'')+'"></label><label class="agenda-wide">Observações<textarea name="notes" maxlength="1000" rows="3">'+esc(r?.notes||'')+'</textarea></label><label class="agenda-wide">Foto ou logotipo (opcional, até 120 KB)<input name="image" type="file" accept="image/png,image/jpeg,image/webp"></label></div><label class="agenda-fav"><input name="favorite" type="checkbox" '+(r?.favorite?'checked':'')+'> Marcar como contato favorito ★</label><p class="agenda-form-message" role="status"></p><div class="agenda-form-actions"><button type="button" data-cancel>Cancelar</button><button type="submit">Salvar contato</button></div></form>';}
function render(){if(!root)return;const filtered=records.filter(r=>(category==='Todos'||r.category===category)&&[r.name,r.company,r.materials,r.category,r.phone].join(' ').toLowerCase().includes(search.toLowerCase())).sort((a,b)=>Number(b.favorite)-Number(a.favorite)||a.company.localeCompare(b.company,'pt-BR')||a.name.localeCompare(b.name,'pt-BR'));const current=records.find(r=>r.id===selected);root.innerHTML='<div class="agenda-shell"><div class="agenda-hero"><div><span class="agenda-eyebrow">🏆 COLAFIX • EDIÇÃO FORNECEDORES</span><h2>Álbum de Parceiros</h2><p>Seus contatos comerciais organizados como uma coleção de figurinhas.</p></div><button class="agenda-add" data-new>＋ Nova figurinha</button></div><div class="agenda-toolbar"><input id="agenda-search" placeholder="⌕ Buscar contato, empresa ou material..." aria-label="Buscar fornecedores" value="'+esc(search)+'"><select id="agenda-category" aria-label="Filtrar por material"><option>Todos</option>'+categories.map(c=>'<option '+(category===c?'selected':'')+'>'+esc(c)+'</option>').join('')+'</select><span>'+filtered.length+' de '+records.length+' contatos</span></div><div class="agenda-layout"><div class="agenda-stickers">'+(filtered.length?filtered.map((r,i)=>sticker(r,i)).join(''):'<div class="agenda-empty">Nenhuma figurinha encontrada. Clique em “Nova figurinha” para cadastrar o primeiro fornecedor.</div>')+'</div><aside class="agenda-detail">'+(editing!==null?form(editing==='new'?null:records.find(r=>r.id===editing)):details(current))+'</aside></div></div>';bind();}
function bind(){root.querySelector('#agenda-search')?.addEventListener('input',e=>{search=e.target.value;const start=e.target.selectionStart;render();const inp=root.querySelector('#agenda-search');inp.focus();inp.setSelectionRange(start,start)});root.querySelector('#agenda-category')?.addEventListener('change',e=>{category=e.target.value;render()});root.querySelector('[data-new]')?.addEventListener('click',()=>{editing='new';render()});root.querySelectorAll('[data-select]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.select;editing=null;render()}));root.querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>{editing=b.dataset.edit;render()}));root.querySelectorAll('[data-cancel]').forEach(b=>b.addEventListener('click',()=>{editing=null;render()}));root.querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',async()=>{const r=records.find(x=>x.id===b.dataset.remove);if(!r||!confirm('Excluir o contato '+r.name+' de '+r.company+'?'))return;try{const response=await fetch('/api/supplier-contacts/'+encodeURIComponent(r.id),{method:'DELETE'});if(!response.ok)throw Error((await response.json()).error||'Falha ao excluir');records=records.filter(x=>x.id!==r.id);selected='';render()}catch(e){alert(e.message)}}));root.querySelector('#agenda-form')?.addEventListener('submit',save);}
async function save(e){e.preventDefault();const form=e.currentTarget,button=form.querySelector('[type=submit]'),msg=form.querySelector('.agenda-form-message'),data=Object.fromEntries(new FormData(form));data.favorite=form.elements.favorite.checked;delete data.image;if(editing!=='new')data.id=editing;const file=form.elements.image.files[0];if(file){if(file.size>120000){msg.textContent='A imagem deve ter até 120 KB.';return;}data.photo=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}else if(editing!=='new')data.photo=records.find(r=>r.id===editing)?.photo||'';button.disabled=true;msg.textContent='Salvando...';try{const response=await fetch('/api/supplier-contacts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error||'Não foi possível salvar');const i=records.findIndex(r=>r.id===result.record.id);if(i>=0)records[i]=result.record;else records.push(result.record);selected=result.record.id;editing=null;render()}catch(error){msg.textContent=error.message;button.disabled=false;}}
async function load(){if(!root)return;root.innerHTML='<p class="agenda-loading">Carregando agenda...</p>';try{const response=await fetch('/api/supplier-contacts',{cache:'no-store'});if(!response.ok)throw Error('Não foi possível carregar os contatos');const data=await response.json();records=Array.isArray(data.records)?data.records:[];render()}catch(e){root.innerHTML='<div class="agenda-error">'+esc(e.message)+' <button id="agenda-retry">Tentar novamente</button></div>';root.querySelector('#agenda-retry').onclick=load}}
if(root){load();window.addEventListener('hashchange',()=>{if(location.hash==='#agenda')load()})}
